// Package blocks reads and writes BlockSuite documents — the Yjs state of an
// aenotes page or board — on the server, for tools that work with content
// (the MCP server): a document as Markdown, and Markdown as new blocks.
//
// The block shape is BlockSuite's own (affine 0.22): the "blocks" map holds
// one Y.Map per block with sys:id, sys:flavour, sys:version, sys:children (a
// Y.Array of child ids) and its props as prop:<name> — text as Y.Text, nested
// objects as Y.Maps. Blocks written here carry the same keys and defaults
// BlockSuite gives them (see the testdata generated by BlockSuite itself), so
// the editor treats them as its own.
package blocks

import (
	"crypto/rand"
	"errors"
	"fmt"
	"strings"

	"github.com/reearth/ygo/crdt"
)

// Block is one block, read.
type Block struct {
	ID       string
	Flavour  string
	Props    map[string]any
	Text     []crdt.Delta
	Children []*Block
}

// Doc is a document loaded from its state.
type Doc struct {
	doc    *crdt.Doc
	blocks *crdt.YMap
	Root   *Block
}

// ErrNoRoot is returned for a state without an affine:page block.
var ErrNoRoot = errors.New("blocks: the document has no root block")

// Load reads a document's state.
func Load(state []byte) (*Doc, error) {
	doc := crdt.New()
	if err := crdt.ApplyUpdateV1(doc, state, nil); err != nil {
		return nil, err
	}
	d := &Doc{doc: doc, blocks: doc.GetMap("blocks")}
	for _, k := range d.blocks.Keys() {
		if m, ok := d.ymap(k); ok {
			if f, _ := m.Get("sys:flavour"); f == "affine:page" {
				d.Root = d.read(k, map[string]bool{})
				break
			}
		}
	}
	if d.Root == nil {
		return nil, ErrNoRoot
	}
	return d, nil
}

func (d *Doc) ymap(id string) (*crdt.YMap, bool) {
	v, ok := d.blocks.Get(id)
	if !ok {
		return nil, false
	}
	m, ok := v.(*crdt.YMap)
	return m, ok
}

// read builds the block tree under id (seen guards against a cycle in a
// damaged document).
func (d *Doc) read(id string, seen map[string]bool) *Block {
	m, ok := d.ymap(id)
	if !ok || seen[id] {
		return nil
	}
	seen[id] = true
	b := &Block{ID: id, Props: map[string]any{}}
	if f, ok := m.Get("sys:flavour"); ok {
		b.Flavour, _ = f.(string)
	}
	for _, k := range m.Keys() {
		if !strings.HasPrefix(k, "prop:") {
			continue
		}
		v, _ := m.Get(k)
		name := strings.TrimPrefix(k, "prop:")
		switch t := v.(type) {
		case *crdt.YText:
			if name == "text" {
				b.Text = t.ToDelta()
			} else {
				b.Props[name] = t.ToString()
			}
		default:
			b.Props[name] = v
		}
	}
	if c, ok := m.Get("sys:children"); ok {
		if arr, ok := c.(*crdt.YArray); ok {
			for _, x := range arr.ToSlice() {
				if cid, ok := x.(string); ok {
					if child := d.read(cid, seen); child != nil {
						b.Children = append(b.Children, child)
					}
				}
			}
		}
	}
	return b
}

// Title is the document's title (the root block's title text).
func (d *Doc) Title() string {
	t, _ := d.Root.Props["title"].(string)
	return t
}

// Notes returns the root's notes in order: what a page shows top to bottom
// (onPage) or every note on the canvas.
func (d *Doc) Notes(onPage bool) []*Block {
	var out []*Block
	for _, c := range d.Root.Children {
		if c.Flavour != "affine:note" {
			continue
		}
		if onPage && c.Props["displayMode"] == "edgeless" {
			continue
		}
		out = append(out, c)
	}
	return out
}

// Shapes returns the text of the canvas elements that carry some (shapes,
// text elements, connector labels), for a board's summary.
func (d *Doc) Shapes() []string {
	var out []string
	for _, c := range d.Root.Children {
		if c.Flavour != "affine:surface" {
			continue
		}
		m, ok := d.ymap(c.ID)
		if !ok {
			continue
		}
		elems, _ := m.Get("prop:elements")
		em, ok := elems.(*crdt.YMap)
		if !ok {
			continue
		}
		val, _ := em.Get("value")
		vm, ok := val.(*crdt.YMap)
		if !ok {
			continue
		}
		for _, k := range vm.Keys() {
			ev, _ := vm.Get(k)
			e, ok := ev.(*crdt.YMap)
			if !ok {
				continue
			}
			typ, _ := e.Get("type")
			txt := ""
			for _, key := range []string{"text", "label"} {
				if t, ok := e.Get(key); ok {
					if yt, ok := t.(*crdt.YText); ok && yt.ToString() != "" {
						txt = yt.ToString()
					}
				}
			}
			if txt != "" {
				out = append(out, fmt.Sprintf("%v: %s", typ, txt))
			}
		}
	}
	return out
}

const idAlphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_-"

// newID mints a block id in BlockSuite's shape (10 url-safe characters).
func newID() string {
	var b [10]byte
	_, _ = rand.Read(b[:])
	for i := range b {
		b[i] = idAlphabet[int(b[i])%len(idAlphabet)]
	}
	return string(b[:])
}

// Links lists the documents this one links to, in the order they appear:
// references in text (@-mentions) and linked or synced document cards. It
// is what the sidebar shows as the document's children (AFFiNE's rule).
func (d *Doc) Links() []string {
	var out []string
	seen := map[string]bool{}
	add := func(id string) {
		if id != "" && !seen[id] {
			seen[id] = true
			out = append(out, id)
		}
	}
	var walk func(b *Block)
	walk = func(b *Block) {
		switch b.Flavour {
		case "affine:embed-linked-doc", "affine:embed-synced-doc":
			id, _ := b.Props["pageId"].(string)
			add(id)
		}
		for _, op := range b.Text {
			if ref, ok := op.Attributes["reference"].(map[string]any); ok {
				id, _ := ref["pageId"].(string)
				add(id)
			}
		}
		for _, c := range b.Children {
			walk(c)
		}
	}
	walk(d.Root)
	return out
}
